begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','99500000-0000-4000-8000-000000000001','authenticated','authenticated','jobs-owner@example.test','',now(),'{"display_name":"Mang Ben"}',now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','99500000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99500000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_business('job-orders-test','Job Orders Test','Job Orders Test','sole_proprietorship','services','{"city":"Manila"}');select set_config('test.job_org',(select id::text from public.organizations where slug='job-orders-test'),true);select set_config('test.job_branch',(select id::text from public.branches where organization_id=current_setting('test.job_org')::uuid and code='main'),true);
select is(public.can_business_permission(current_setting('test.job_org')::uuid,'job-orders.manage'),true,'Owner receives job-order permissions');
select results_eq($$select count(*)from public.role_permissions assignment join public.roles role on role.id=assignment.role_id join public.permissions permission on permission.id=assignment.permission_id where role.organization_id=current_setting('test.job_org')::uuid and role.key='manager'and permission.key like'job-orders.%'$$,$$select 4::bigint$$,'Managers receive every Job Order permission');
select throws_ok($$select public.save_job_order(current_setting('test.job_org')::uuid,current_setting('test.job_branch')::uuid,gen_random_uuid(),null,null,'Repair','Test','normal',null,null,'','[]','[]')$$,'42501','Permission denied.','Disabled module rejects writes');
reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.job_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','99500000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99500000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.set_business_module_state(current_setting('test.job_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.job_org')::uuid,'inventory',true,'{"allow_negative_stock":false}');select public.set_business_module_state(current_setting('test.job_org')::uuid,'crm',true,'{}');
select lives_ok($$select public.set_business_module_state(current_setting('test.job_org')::uuid,'job_orders',true,'{"singular_label":"Repair Order","plural_label":"Repair Orders","consume_inventory":true,"consumption_trigger":"on_start"}')$$,'Job Orders activate with catalog, inventory, and CRM dependencies');
select results_eq($$select config->>'singular_label',config->>'plural_label' from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=current_setting('test.job_org')::uuid and definition.key='job_orders'$$,$$select 'Repair Order'::text,'Repair Orders'::text$$,'Business templates can rename the module');
select results_eq($$select display_name,status from public.job_order_staff where organization_id=current_setting('test.job_org')::uuid$$,$$select 'Mang Ben'::text,'active'::text$$,'Active members become assignable staff');select set_config('test.job_staff',(select id::text from public.job_order_staff where organization_id=current_setting('test.job_org')::uuid),true);
select set_config('test.job_customer',public.save_crm_customer(current_setting('test.job_org')::uuid,null,current_setting('test.job_branch')::uuid,'Maria Santos','09171234567','','{}',null,null,'retail','{}','')::text,true);
select set_config('test.job_service',public.save_catalog_product(current_setting('test.job_org')::uuid,null,null,'service','Appliance Repair','',null,null,'piece',1200,0,'exempt',0,'active',false,'[{"name":"Default","sku":"SVC-REPAIR","barcode":"","attributes":{},"status":"active"}]','[]')::text,true);
select set_config('test.job_product',public.save_catalog_product(current_setting('test.job_org')::uuid,null,null,'product','Replacement Motor','',null,null,'piece',700,400,'inclusive',12,'active',false,'[{"name":"Default","sku":"MOTOR-001","barcode":"","attributes":{},"status":"active"}]','[]')::text,true);select set_config('test.job_variant',(select id::text from public.product_variants where product_id=current_setting('test.job_product')::uuid),true);select set_config('test.job_item',public.configure_inventory_item(current_setting('test.job_org')::uuid,null,current_setting('test.job_variant')::uuid,2,4,true)::text,true);select set_config('test.job_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.job_org')::uuid),true);select public.record_stock_movement(current_setting('test.job_org')::uuid,current_setting('test.job_item')::uuid,current_setting('test.job_location')::uuid,'opening_balance',10,400,'Opening','job-opening');
select set_config('test.job1',public.save_job_order(current_setting('test.job_org')::uuid,current_setting('test.job_branch')::uuid,current_setting('test.job_customer')::uuid,current_setting('test.job_staff')::uuid,current_setting('test.job_service')::uuid,'Repair','Replace failed motor','urgent',current_date,current_date+2,'Handle carefully','[{"description":"Diagnostics","hours":1.5,"hourlyRate":450}]',('[{"productVariantId":"'||current_setting('test.job_variant')||'","inventoryLocationId":"'||current_setting('test.job_location')||'","description":"Replacement Motor","quantity":2}]')::jsonb)::text,true);
select results_eq($$select job_number,status,priority,service_type,start_date,due_date from public.job_orders where id=current_setting('test.job1')::uuid$$,$$select 'JOB-'||extract(year from current_date)::integer||'-000001','new'::text,'urgent'::text,'Repair'::text,current_date,current_date+2$$,'Job order stores requested work and schedule');
select results_eq($$select labor_total,material_total from public.job_orders where id=current_setting('test.job1')::uuid$$,$$select 675::numeric,800::numeric$$,'Labor and material estimates are calculated server-side');
select results_eq($$select count(*)from public.stock_movements where reference_type='job_order'and reference_id=current_setting('test.job1')::uuid$$,$$select 0::bigint$$,'Planning materials never changes inventory');
select lives_ok($$select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid,'accepted','Accepted')$$,'New work can be accepted');
select results_eq($$select quantity from public.stock_balances where inventory_item_id=current_setting('test.job_item')::uuid$$,$$select 10::numeric$$,'Acceptance does not consume on an on-start configuration');
select lives_ok($$select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid,'in_progress','Started')$$,'Starting work atomically consumes configured materials');
select results_eq($$select status from public.job_orders where id=current_setting('test.job1')::uuid$$,$$select 'in_progress'::text$$,'Lifecycle advances after material posting');
select results_eq($$select quantity from public.stock_balances where inventory_item_id=current_setting('test.job_item')::uuid$$,$$select 8::numeric$$,'Material consumption reduces the material location balance');
select results_eq($$select movement_type,quantity_delta,reference_type,reference_id from public.stock_movements where reference_type='job_order'and reference_id=current_setting('test.job1')::uuid$$,$$select 'sale'::text,-2::numeric,'job_order'::text,current_setting('test.job1')::uuid$$,'Consumption creates an immutable referenced stock movement');
select results_eq($$select planned_quantity,consumed_quantity from public.job_order_material_items where job_order_id=current_setting('test.job1')::uuid$$,$$select 2::numeric,2::numeric$$,'Material line records consumed quantity');
select lives_ok($$select public.consume_job_order_materials(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid)$$,'Consumption can be retried safely');
select results_eq($$select count(*)from public.stock_movements where reference_type='job_order'and reference_id=current_setting('test.job1')::uuid$$,$$select 1::bigint$$,'Retry cannot duplicate the stock movement');
select lives_ok($$select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid,'waiting','Waiting for customer');select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid,'in_progress','Resumed')$$,'Work can wait and resume');
select results_eq($$select count(*)from public.stock_movements where reference_type='job_order'and reference_id=current_setting('test.job1')::uuid$$,$$select 1::bigint$$,'Resuming work does not consume twice');
select lives_ok($$select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid,'completed','Done');select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid,'released','Released')$$,'Completed work can be released');
select results_eq($$select status,completed_date from public.job_orders where id=current_setting('test.job1')::uuid$$,$$select 'released'::text,current_date$$,'Completion date persists through release');
select throws_ok($$select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job1')::uuid,'accepted','Reopen')$$,'P0001','Invalid job order status transition.','Released work is terminal');
select set_config('test.job2',public.save_job_order(current_setting('test.job_org')::uuid,current_setting('test.job_branch')::uuid,current_setting('test.job_customer')::uuid,null,null,'Repair','Impossible stock','normal',null,null,'','[]',('[{"productVariantId":"'||current_setting('test.job_variant')||'","inventoryLocationId":"'||current_setting('test.job_location')||'","description":"Replacement Motor","quantity":20}]')::jsonb)::text,true);select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job2')::uuid,'accepted','Accepted');
select throws_ok($$select public.change_job_order_status(current_setting('test.job_org')::uuid,current_setting('test.job2')::uuid,'in_progress','Start')$$,'P0001','Insufficient stock.','Insufficient stock aborts the status transaction');
select results_eq($$select status from public.job_orders where id=current_setting('test.job2')::uuid$$,$$select 'accepted'::text$$,'Failed consumption leaves lifecycle unchanged');
select results_eq($$select consumed_quantity from public.job_order_material_items where job_order_id=current_setting('test.job2')::uuid$$,$$select 0::numeric$$,'Failed consumption leaves material progress unchanged');
select results_eq($$select quantity from public.stock_balances where inventory_item_id=current_setting('test.job_item')::uuid$$,$$select 8::numeric$$,'Failed consumption leaves stock unchanged');
select results_eq($$select count(*)from public.job_order_audit_history where job_order_id=current_setting('test.job1')::uuid and event in('created','status_changed','materials_consumed')$$,$$select 10::bigint$$,'Creation, transitions, and material attempts are audited');
select * from finish();rollback;
